window.renderMetroCase=(t,href)=>{
 const img=(file,zh,en)=>`<figure><img src="assets/metro/${file}.jpg" alt="${t(zh,en)}" loading="lazy"></figure>`;
 const text=(n,zh,en,cz,ce)=>`<section class="metro-copy reveal"><span>${n}</span><div><h2>${t(zh,en)}</h2><p>${t(cz,ce)}</p></div></section>`;
 return `<article class="metro-case"><header class="metro-heading"><a href="${href('work')}">↖ ${t('全部案例','All projects')}</a><p>2021 / Xianyu</p><h1>${t('闲鱼文学奖<br>地铁车厢视觉设计','Xianyu Literature Awards<br>Metro Exhibition')}</h1><p>${t('将线上的趣味表达，带入日常通勤空间。','Bringing playful online expression into everyday journeys.')}</p></header>
 ${img('01-cover','车厢地面上的闲鱼体与人物轮廓','Xianyu wordplay and silhouettes on the carriage floor')}
 <section class="metro-overview reveal"><div><h2>${t('传播时间线','Campaign timeline')}</h2><ol>${[
 ['2021.04.12','发起「闲鱼体」讨论','“Xianyu-style” discussion begins'],['2021.04.14','定义「闲鱼体」：官方表态、征集活动与文学研究','Defining the style: official messaging, submissions and literary exploration'],['2021.04.19','「闲鱼体」生成器传播、闲鱼文学奖宣言','Style generator promotion and Literature Awards manifesto'],['2021.04.20','「闲鱼体」地铁展览','Metro exhibition'],['2021.04.23','闲鱼文学奖颁奖典礼传播','Awards ceremony communication']].map(([d,z,e])=>`<li><time>${d}</time><span>${t(z,e)}</span></li>`).join('')}</ol></div><div><h2>${t('项目背景','Overview')}</h2><p>${t('在闲鱼 APP 上，卖家为了卖东西、买家为了买东西，迸射出奇怪的智慧，形成了独特的「闲鱼体」。通过强化这一概念，传递闲鱼有趣、年轻的品牌心智。','On Xianyu, the exchanges between buyers and sellers give rise to an inventive style of everyday writing. The campaign framed this distinctive voice as “Xianyu-style”, expressing the brand’s playful, youthful character.')}</p><p>${t('地铁车厢展览是「闲鱼文学奖」传播中的一个分支：将闲鱼文学可视化，打造移动的地铁车厢展览，并以打卡拍照与线上分享为传播目标。','The metro exhibition formed one part of the Xianyu Literature Awards campaign. It translated online writing into a moving exhibition, designed to invite photographs and further sharing online.')}</p><dl><dt>${t('传播目的','Objective')}</dt><dd>${t('传递「年轻、有趣」的闲鱼心智','Express a youthful, playful brand')}</dd><dt>${t('用户群体','Audience')}</dt><dd>${t('追求创意、潮流的年轻人','Young people drawn to creativity and contemporary culture')}</dd><dt>${t('传播渠道','Channels')}</dt><dd>${t('小红书、新闻稿','Rednote and press releases')}</dd></dl></div></section>
 ${text('01','设计思路','Design approach','强化「闲鱼体」内容、营造地铁氛围、突出闲鱼品牌。以完整的商品图文与精炼句子呈现内容，结合创意插画、打卡区域和品牌黄色建立整体视觉。','The approach brings together Xianyu-style writing, the carriage environment and brand recognition. Full listings and short quotations sit alongside illustrations, photo opportunities and the brand’s signature yellow.')}
 <div class="metro-strategy reveal">${[['闲鱼体','Xianyu-style writing','商品图文 · 精炼句子','Full listings · Short quotations'],['地铁氛围','Carriage experience','创意插画 · 打卡区域','Illustration · Photo opportunities'],['品牌强调','Brand expression','闲鱼品牌黄','Signature Xianyu yellow']].map(([z,e,sz,se])=>`<div><h3>${t(z,e)}</h3><p>${t(sz,se)}</p></div>`).join('')}</div>
 ${text('02','地铁内部可视化区域','Mapping the carriage','根据车厢内部空间，将设计区域分为驾驶舱背面、车顶、车身、车门、车窗、广告牌与地面。各处可视面积和观看方式不同，因此内容的主次与功能也有所区别。','The interior was divided into the cab partition, ceiling, walls, doors, windows, advertising panels and floor. Different viewing conditions and surface areas informed the hierarchy and function of each element.')}
 <ol class="metro-zones reveal">${[['驾驶舱背面','Cab partition','创意打卡点','Photo opportunity'],['列车车顶','Ceiling','闲鱼弹窗','Pop-up messages'],['车门玻璃','Door windows','闲鱼对话框','Conversation bubbles'],['列车车身','Walls','闲鱼体','Xianyu-style quotations'],['车窗玻璃','Windows','座位分区标签','Seat-zone labels'],['广告牌','Ad panels','商品与闲鱼体','Listings and writing'],['列车地面','Floor','创意图文','Illustrated text']].map(([z,e,sz,se])=>`<li><strong>${t(z,e)}</strong><span>${t(sz,se)}</span></li>`).join('')}</ol>
 ${img('02-carriage','黄色主题地铁车厢全景','Overview of the yellow metro carriage')}
 ${text('03','列车地面设计','The floor','将精选的闲鱼趣味句子与六个人物轮廓结合。设计考虑乘客低头看手机的日常姿态，希望乘客偶然读到脚边的句子时，获得惊喜；人物影子同时提示座位位置。','Six outlined figures were paired with selected quotations. The design responds to passengers looking down at their phones, placing small discoveries at their feet while the silhouettes also suggest seating positions.')}
 ${img('03-floor','六个人物轮廓与地面文字','Floor silhouettes and quotations')}<div class="metro-pair">${img('04-floor-left','乘客脚边的地面设计','Floor graphics beside a passenger’s shoes')}${img('05-floor-right','地面趣味文案局部','Detail of playful floor copy')}</div>
 ${text('04','车身与窗户玻璃贴纸','Walls and window graphics','车身内容以对话框呈现简短段落或句子。车窗贴纸依据每节车厢的六个座位区块，划分为「当代文豪区」「闲鱼翻身区」「聊天升级选手」「生活艺术家」「生活精算师」「鱼世无争区」。','Short passages and quotations appear as conversation bubbles on the walls. Window stickers give the six seating zones playful identities, including contemporary writers, bargain-minded everyday strategists and laid-back passengers.')}
 ${img('06-wall-collage','车身对话框与座位分区的实景组合','Wall quotations and seat-zone labels in use')}
 ${text('05','车门玻璃贴','Door-window conversations','考虑车门开关与聊天对话的相似动态，使用闲鱼买卖双方的真实沟通内容，将对话框分别放在两扇车门上。','The opening and closing doors echo the back-and-forth of a chat. Actual buyer–seller exchanges are split between the two door windows.')}
 <div class="metro-pair">${img('07-dialogue','买卖双方的对话框设计','Buyer–seller dialogue artwork')}${img('08-doors','对话框在地铁车门上的应用','Dialogue bubbles applied to carriage doors')}</div>
 ${text('06','广告牌设计','Advertising panels','以商品页面的图文形式展示闲鱼文学内容，让原本发生在交易页面里的表达，进入实体车厢的阅读场景。','Listing-style layouts bring the writing and imagery of the marketplace into the physical carriage, retaining the context in which the language originated.')}
 <div class="metro-pair">${img('09-ad-installed','车厢广告框内的闲鱼文学作品','A Xianyu literary listing displayed in an advertising frame')}${img('10-ad-layout','两张商品图文设计','Two listing-based layouts')}</div>
 ${img('11-character','黄色车厢中的黑色人物插画','Black character illustration against the yellow carriage')}
 ${text('07','座位边与车身拐角','Seats and corners','根据乘客坐下后头部的大概位置布置互动小插画，结合地铁乘客的状态，让人与车厢图案产生不经意的互动，形成可记录的画面。','Small interactive illustrations were placed around the approximate head height of seated passengers. Everyday gestures complete the graphics, creating spontaneous moments worth photographing.')}
 <div class="metro-pair">${img('12-interaction','乘客与问号气泡互动','A passenger completing a question-mark illustration')}${img('13-corner','车厢拐角的插画和文案','Illustration and quotation in a carriage corner')}</div>
 ${text('08','驾驶舱背面设计','The cab partition','利用较大的可视面积强化闲鱼品牌，并设置「翻身」的互动打卡画面。车身其他区域已经充分呈现「闲鱼体」，此处转而突出品牌与拍照互动。','The larger cab-partition surface emphasizes the Xianyu brand and an interactive “turn things around” photo moment. With the writing already present throughout the carriage, this area focuses on brand recognition and participation.')}
 ${img('14-brand-interaction','乘客与翻身图案互动','A passenger interacting with the flip-panel graphic')}${img('15-brand-wall','驾驶舱背面的闲鱼品牌视觉','Xianyu brand graphics across the cab partition')}${img('16-ceiling','扶手旁的闲鱼弹窗文案','A listing-inspired pop-up beside the handrail')}
 ${text('09','从线下体验到线上分享','From carriage to sharing','原项目记录提到，乘客通过拍照将地铁内容分享到小红书、微博等平台。这里保留这一传播路径说明；当前资料未提供可核对的传播量或曝光数据。','The original project record describes passengers photographing the carriage and sharing it on platforms including Rednote and Weibo. This documents the sharing mechanism; the supplied material contains no independently verifiable reach or impression figures.')}
 ${img('17-sharing','用手机记录车厢设计','Photographing the carriage design')}
 <aside class="metro-credit">${t('资料整理说明：依据原项目长图拆分与转写；照片及设计画面中的文字保留原貌。具体设计职责、合作团队与署名待补充确认。','Editorial note: reconstructed from the supplied long-form case image. Text within photographs and artwork is retained. Specific design responsibilities, collaborators and credits remain to be confirmed.')}</aside><a class="metro-return" href="${href('work')}">↖ ${t('返回全部案例','Back to all projects')}</a></article>`;
};
